{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "np.where(df['spkts'] > 0, np.isclose(df['smean'], df['sbytes'] / df['spkts'], rtol=0.01, atol=0.5), True)",
        "np.where(df['spkts'] > 0, np.isclose(df['smean'], np.floor(df['sbytes'] / df['spkts']), rtol=0.01, atol=0.5), True)"
      ],
      "features": ["smean", "sbytes", "spkts"],
      "rationale": "Mean packet size from source is defined as source bytes divided by source packet count."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "np.where(df['dpkts'] > 0, np.isclose(df['dmean'], df['dbytes'] / df['dpkts'], rtol=0.01, atol=0.5), True)",
        "np.where(df['dpkts'] > 0, np.isclose(df['dmean'], np.floor(df['dbytes'] / df['dpkts']), rtol=0.01, atol=0.5), True)"
      ],
      "features": ["dmean", "dbytes", "dpkts"],
      "rationale": "Mean packet size from destination is defined as destination bytes divided by destination packet count."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['sload'], (df['sbytes'] * 8) / df['dur'], rtol=0.01), True)"
      ],
      "features": ["sload", "sbytes", "dur"],
      "rationale": "Source load is defined as source bits per second, computed as source bytes times 8 divided by duration."
    },
    {
      "id": "R4",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['dload'], (df['dbytes'] * 8) / df['dur'], rtol=0.01), True)"
      ],
      "features": ["dload", "dbytes", "dur"],
      "rationale": "Destination load is defined as destination bits per second, computed as destination bytes times 8 divided by duration."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "np.where(df['spkts'] > 0, np.isclose(df['sinpkt'], (df['dur'] * 1000) / df['spkts'], rtol=0.01), True)",
        "np.where(df['spkts'] > 1, np.isclose(df['sinpkt'], (df['dur'] * 1000) / (df['spkts'] - 1), rtol=0.01), True)"
      ],
      "features": ["sinpkt", "dur", "spkts"],
      "rationale": "Source interpacket arrival time is the average time between source packets, either total duration divided by packet count or by count minus one."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "np.where(df['dpkts'] > 0, np.isclose(df['dinpkt'], (df['dur'] * 1000) / df['dpkts'], rtol=0.01), True)",
        "np.where(df['dpkts'] > 1, np.isclose(df['dinpkt'], (df['dur'] * 1000) / (df['dpkts'] - 1), rtol=0.01), True)"
      ],
      "features": ["dinpkt", "dur", "dpkts"],
      "rationale": "Destination interpacket arrival time is the average time between destination packets, either total duration divided by packet count or by count minus one."
    },
    {
      "id": "R7",
      "category": "math",
      "alternatives": [
        "np.isclose(df['tcprtt'], df['synack'] + df['ackdat'], rtol=0.01)"
      ],
      "features": ["tcprtt", "synack", "ackdat"],
      "rationale": "TCP round-trip time is defined as the sum of SYN-ACK and ACK times."
    },
    {
      "id": "R8",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['rate'], (df['spkts'] + df['dpkts']) / df['dur'], rtol=0.01), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], df['spkts'] / df['dur'], rtol=0.01), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], (df['sbytes'] + df['dbytes']) / df['dur'], rtol=0.01), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], (df['sbytes'] * 8 + df['dbytes'] * 8) / df['dur'], rtol=0.01), True)"
      ],
      "features": ["rate", "spkts", "dpkts", "sbytes", "dbytes", "dur"],
      "rationale": "Rate is undocumented; plausible definitions include total packets per second, source packets per second, total bytes per second, or total bits per second."
    }
  ]
}
